      const job = fromRow(db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as never) as Job;
      db.exec('COMMIT'); return send(res,201,job);
    } catch (e) { db.exec('ROLLBACK'); console.error(e); return error(res,500,'internal_error','Unable to create job.'); }
  }
