    const job = fromRow(db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as never);
    if (!job) return error(res,404,'not_found','Job not found.');
    return send(res,200,job);
  }
  if (pathname === '/api/jobs' || pathname === '/') return error(res,405,'method_not_allowed','Method not allowed.');
  return error(res,404,'not_found','Not found.');
