const db = openDatabase();
let stopping = false;
let active = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running job has lost its in-memory step position after a worker crash. Queue it again;
// the already-started attempt remains counted, so retries remain bounded at three attempts.
db.exec(`UPDATE jobs SET status='queued', progress_completed=0, updated_at='${new Date().toISOString()}', available_at=0 WHERE status='running';
  UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at='${new Date().toISOString()}' WHERE status='queued' AND attempts>=3;`);

async function runOne(): Promise<boolean> {
  db.exec('BEGIN IMMEDIATE');
  let row: {id:string;input:string;steps:number;fail_attempts:number;attempts:number}|undefined;
  try {
    row = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
      WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as typeof row;
    if (!row) { db.exec('COMMIT'); return false; }
    const now = new Date().toISOString();
    db.prepare(`UPDATE jobs SET status='running',attempts=attempts+1,progress_completed=0,
      result_output=NULL,error=NULL,updated_at=? WHERE id=? AND status='queued'`).run(now,row.id);
    row.attempts += 1;
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }

  active = true;
  try {
    if (row.attempts <= row.fail_attempts) {
      // Deliberately fail before doing any work for this simulated dependency outage.
      await sleep(10);
      const now = new Date().toISOString();
      if (row.attempts >= 3) {
        db.prepare(`UPDATE jobs SET status='failed',error='transient failure',result_output=NULL,updated_at=? WHERE id=? AND status='running'`).run(now,row.id);
      } else {
        db.prepare(`UPDATE jobs SET status='queued',progress_completed=0,available_at=?,updated_at=? WHERE id=? AND status='running'`).run(Date.now()+500,now,row.id);
      }
      return true;
    }
    for (let step=1; step<=row.steps; step++) {
      await sleep(100);
      db.prepare(`UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'`).run(step,new Date().toISOString(),row.id);
    }
    db.prepare(`UPDATE jobs SET status='completed',result_output=?,error=NULL,updated_at=? WHERE id=? AND status='running'`)
      .run(row.input.toUpperCase(),new Date().toISOString(),row.id);
    return true;
  } finally { active = false; }
}

console.log('worker started');
try {
  while (!stopping) {
    db.prepare(`INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
    if (!stopping) await runOne();
    if (!active) await sleep(100);
  }
} finally {
  db.close();
  process.exit(0);
}
