<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form">
    <label>Input <input data-testid="job-input" name="input" type="text" maxlength="1000"></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorRegion = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    const input = document.querySelector('[data-testid="job-input"]');
    const steps = document.querySelector('[data-testid="job-steps"]');
    const failAttempts = document.querySelector('[data-testid="job-fail-attempts"]');
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li'); item.className = 'job';
        item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
        const title = document.createElement('strong'); title.textContent = job.input;
        const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
        const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
        const result = document.createElement('span'); result.dataset.testid = 'job-result';
        result.textContent = job.result?.output ?? job.error ?? '';
        const p1 = document.createElement('p'); p1.append(title);
        const p2 = document.createElement('p'); p2.className = 'meta'; p2.append('Status: ', status, ' · Progress: ', progress);
        const p3 = document.createElement('p'); p3.append('Result: ', result);
        item.append(p1,p2,p3); return item;
      }));
    }
    async function refresh() {
      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); }
      catch (_) { /* refresh on the next poll */ }
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); errorRegion.textContent = '';
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: {'Content-Type':'application/json'},
          body: JSON.stringify({input: input.value, steps: Number(steps.value), failAttempts: Number(failAttempts.value)}) });
        const data = await response.json();
        if (!response.ok) {
          const fields = data.error?.fields;
          errorRegion.textContent = fields?.length ? fields.map(f => `${f.field}: ${f.message}`).join(' ') : (data.error?.message ?? 'Submission failed.');
        } else { input.value = ''; await refresh(); }
      } catch (_) { errorRegion.textContent = 'Unable to submit job.'; }
    });
    refresh(); setInterval(refresh, 500);
  </script>
</body>
